import SwiftUI
import SwiftData

@main
struct HabitsApp: App {
    @State private var env = AppEnvironment()

    var body: some Scene {
        WindowGroup {
            RootView()
                .environment(env)
        }
        .modelContainer(for: [Habit.self, HabitEntry.self])
    }
}

@Observable
final class AppEnvironment {
    let api: APIClient
    let analytics: Analytics

    init() {
        self.api = APIClient()
        self.analytics = SentryAnalytics()
    }
}

import SwiftData
import Foundation

@Model
final class Habit {
    @Attribute(.unique) var id: UUID
    var name: String
    var emoji: String
    var createdAt: Date
    @Relationship(deleteRule: .cascade) var entries: [HabitEntry]

    init(name: String, emoji: String) {
        self.id = UUID(); self.name = name; self.emoji = emoji
        self.createdAt = .now; self.entries = []
    }
}

@Model
final class HabitEntry {
    @Attribute(.unique) var id: UUID
    var date: Date
    init(date: Date = .now) { self.id = UUID(); self.date = date }
}

// Calculo puro, facil de testar
func calcularStreak(entries: [HabitEntry], hoje: Date = .now) -> Int {
    let cal = Calendar.current
    let dias = Set(entries.map { cal.startOfDay(for: $0.date) })
    var streak = 0
    var cursor = cal.startOfDay(for: hoje)
    while dias.contains(cursor) {
        streak += 1
        cursor = cal.date(byAdding: .day, value: -1, to: cursor)!
    }
    return streak
}

@Observable
final class HabitsViewModel {
    enum State { case idle, loading, loaded, failed(String) }
    var state: State = .idle
    var habits: [Habit] = []

    private let api: APIClient
    init(api: APIClient) { self.api = api }

    @MainActor
    func sync() async {
        state = .loading
        do {
            habits = try await api.send(.habits)
            state = .loaded
        } catch {
            state = .failed(error.localizedDescription)
        }
    }
}
